@@ -0,0 +1,82 @@
+/* test_dissectors.c
+ * Wireshark dissector tests
+ *
+ * Wireshark - Network traffic analyzer
+ * By Gerald Combs <gerald@wireshark.org>
+ * Copyright 1999 Gerald Combs
+ *
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include <glib.h>
+#include <stddef.h>
+
+#include "epan/epan.h"
+#include "epan/packet_info.h"
+#include "epan/proto.h"
+#include "epan/tvbuff.h"
+#include "epan/wmem_scopes.h"
+#include "epan/ftypes/ftypes.h"
+
+#include "wsutil/privileges.h"
+#include "wsutil/wmem/wmem_core.h"
+
+#include "wiretap/wtap.h"
+
+#include "epan/dissectors/packet-bt-dht.c"
+
+tvbuff_t * to_buffer(const char * data, const size_t data_length)
+{
+  g_assert_cmpint(data_length, >, 0);
+  return tvb_new_real_data(data, data_length - 1, data_length - 1);
+}
+
+proto_tree * make_tree(void)
+{
+  packet_info * pinfo = wmem_new(wmem_packet_scope(), packet_info);
+  pinfo->pool = wmem_packet_scope();
+  proto_tree * tree = proto_tree_create_root(pinfo);
+  proto_tree_set_visible(tree, TRUE);
+  return tree;
+}
+
+static void
+bt_dht_read_valid_string(void)
+{
+  const char data[] = "5:value";
+  tvbuff_t * buff = to_buffer(data, sizeof(data));
+  proto_tree * tree = make_tree();
+
+  const char * result;
+  const int offset = dissect_bencoded_string(buff, tree->tree_data->pinfo, tree, 0, &result, FALSE, "Label");
+  g_assert_cmpint(offset, ==, 7);
+  g_assert_cmpstr(result, ==, "value");
+
+  g_assert_true(tree->first_child == tree->last_child);
+  g_assert_true(IS_FT_STRING(tree->first_child->finfo->hfinfo->type));
+  g_assert_cmpstr(tree->first_child->finfo->value.value.string, ==, "value");
+
+  tvb_free(buff);
+  proto_tree_free(tree);
+}
+
+int
+main(int argc, char **argv)
+{
+  g_test_init(&argc, &argv, NULL);
+
+  init_process_policies();
+  wtap_init(0);
+  epan_init(NULL, NULL, 0);
+  wmem_enter_file_scope();
+  wmem_enter_packet_scope();
+
+  g_test_add_func("/bt_dht/read_valid_string",  bt_dht_read_valid_string);
+
+  const int ret = g_test_run();
+  wmem_leave_packet_scope();
+  wmem_leave_file_scope();
+  epan_cleanup();
+  wtap_cleanup();
+  return ret;
+}

